#!/usr/bin/env bash
# Installs the LOZIA Next.js + Supabase project into ./lozia-next in the current directory.
# This script embeds the full project as a base64 tar.gz and extracts it — nothing is downloaded.
set -euo pipefail

TARGET_DIR="lozia-next"
if [[ -e "$TARGET_DIR" ]]; then
  echo "Error: ./$TARGET_DIR already exists. Move it aside or run this from an empty directory." >&2
  exit 1
fi

TMP_ARCHIVE="$(mktemp -t lozia-next-XXXXXX.tar.gz)"
trap 'rm -f "$TMP_ARCHIVE"' EXIT

base64 -d > "$TMP_ARCHIVE" <<'LOZIA_ARCHIVE_EOF'
